        return json{{"vram_mib", eng.vram_used_mib()},
                    {"rss_mib", static_cast<double>(status_kb("VmRSS:")) / 1024.0},
                    {"rss_peak_mib", static_cast<double>(status_kb("VmHWM:")) / 1024.0},
